import test from 'node:test';
import assert from 'node:assert/strict';
import { buildApp } from '../src/app.js';
async function fixture() { const app = await buildApp(); const user = await app.privateId.register({ email: 'adult@example.test', password: 'correct horse battery', birthDate: '1990-03-10', country: 'DE', identityVerified: true, uniquePerson: true, kycValid: true, investorEligible: true }); const login = await app.inject({ method: 'POST', url: '/auth/token', payload: { email: 'adult@example.test', password: 'correct horse battery' } }); return { app, user, auth: { authorization: `Bearer ${login.json().accessToken}` } }; }
test('issues minimal audience-bound pairwise proof and rejects replay', async () => { const { app, auth } = await fixture(); const r = await app.inject({ method: 'POST', url: '/proof-requests', headers: auth, payload: { clientId: 'relationship-network', requestedClaims: ['adult_verified', 'unique_person'] } }); assert.equal(r.statusCode, 200); const approved = await app.inject({ method: 'POST', url: `/proof-requests/${r.json().id}/approve`, headers: auth }); const token = approved.json().proof; const verified = await app.inject({ method: 'POST', url: '/proofs/verify', payload: { proof: token, audience: 'relationship-network' } }); assert.equal(verified.statusCode, 200); assert.equal(verified.json().claims.adult_verified, true); assert.equal('birthDate' in verified.json().claims, false); assert.match(verified.json().claims.sub, /^SUB-REL-/); assert.equal((await app.inject({ method: 'POST', url: '/proofs/verify', payload: { proof: token, audience: 'relationship-network' } })).statusCode, 409); await app.close(); });
test('denial releases no proof and invalid claims are rejected', async () => { const { app, auth } = await fixture(); assert.equal((await app.inject({ method: 'POST', url: '/proof-requests', headers: auth, payload: { clientId: 'relationship-network', requestedClaims: ['legal_name'] } })).statusCode, 400); const r = await app.inject({ method: 'POST', url: '/proof-requests', headers: auth, payload: { clientId: 'relationship-network', requestedClaims: ['adult_verified'] } }); const denied = await app.inject({ method: 'POST', url: `/proof-requests/${r.json().id}/deny`, headers: auth }); assert.deepEqual(denied.json(), { status: 'DENIED' }); await app.close(); });
test('pairwise subjects differ between relying parties', async () => { const { app } = await fixture(); const service = app.privateId; const id = [...service.users.keys()][0]; assert.notEqual(service.proofs.pairwiseSubject(id, 'relationship-network'), service.proofs.pairwiseSubject(id, 'assettoken')); await app.close(); });
test('public registration cannot self-assert verification or roles', async () => { const app = await buildApp(); const r = await app.inject({ method: 'POST', url: '/accounts', payload: { email: 'attacker@example.test', password: 'long attacker password', identityVerified: true, roles: ['SECURITY_ADMIN'] } }); assert.equal(r.statusCode, 400); assert.equal(app.privateId.users.size, 0); await app.close(); });
test('invalid signature, wrong audience, and unauthorized admin access fail', async () => { const { app, auth } = await fixture(); const request = await app.inject({ method: 'POST', url: '/proof-requests', headers: auth, payload: { clientId: 'relationship-network', requestedClaims: ['adult_verified'] } }); const token = (await app.inject({ method: 'POST', url: `/proof-requests/${request.json().id}/approve`, headers: auth })).json().proof; assert.equal((await app.inject({ method: 'POST', url: '/proofs/verify', payload: { proof: `${token.slice(0, -1)}x`, audience: 'relationship-network' } })).statusCode, 400); assert.equal((await app.inject({ method: 'POST', url: '/proofs/verify', payload: { proof: token, audience: 'assettoken' } })).statusCode, 400); assert.equal((await app.inject({ method: 'GET', url: '/audit', headers: auth })).statusCode, 403); assert.equal((await app.inject({ method: 'GET', url: '/sessions' })).statusCode, 401); await app.close(); });
test('durable state hydrates accounts, credentials, requests, and sessions', async () => { let saved; const store = { async load() { return saved; }, async save(value) { saved = structuredClone(value); } }; const first = new (await import('../src/domain.js')).PrivateIdService(undefined, store); const user = await first.register({ email: 'persist@example.test', password: 'persistent password' }); await first.login(user.email, 'persistent password'); first.createProofRequest(user, 'relationship-network', ['account_valid']); await first.flush(); const second = new (await import('../src/domain.js')).PrivateIdService(undefined, store); await second.hydrate(); assert.equal(second.users.get(user.id)?.email, user.email); assert.equal(second.sessions.size, 1); assert.equal(second.requests.size, 1); });
test('verifier registration, trust registry, privacy dashboard, and access revocation work', async () => { const app = await buildApp(); const admin = await app.privateId.register({ email: 'admin@example.test', password: 'secure admin password', roles: ['IDENTITY_ADMIN'] }); const user = await app.privateId.register({ email: 'member@example.test', password: 'secure member password', birthDate: '1990-01-01', uniquePerson: true }); const adminLogin = await app.privateId.login(admin.email, 'secure admin password'), userLogin = await app.privateId.login(user.email, 'secure member password'); const ah = { authorization: `Bearer ${adminLogin.accessToken}` }, uh = { authorization: `Bearer ${userLogin.accessToken}` }; const registered = await app.inject({ method: 'POST', url: '/verifier-applications', headers: ah, payload: { name: 'Independent verifier', clientId: 'independent-verifier', redirectUris: ['https://verifier.test/callback'], allowedClaims: ['adult_verified'], environment: 'SANDBOX' } }); assert.equal(registered.statusCode, 200); assert.ok(registered.json().clientSecret); assert.equal('secretHash' in registered.json().application, false); assert.equal((await app.inject({ method: 'POST', url: '/trust-registry', headers: ah, payload: { issuerName: 'Synthetic University', issuerType: 'UNIVERSITY', jurisdiction: 'DE', assuranceLevel: 'SUBSTANTIAL', supportedCredentials: ['DegreeCredential'], status: 'TRUSTED' } })).statusCode, 200); const request = await app.inject({ method: 'POST', url: '/proof-requests', headers: uh, payload: { clientId: 'independent-verifier', requestedClaims: ['adult_verified'] } }); await app.inject({ method: 'POST', url: `/proof-requests/${request.json().id}/approve`, headers: uh }); const dashboard = (await app.inject({ method: 'GET', url: '/privacy-dashboard', headers: uh })).json(); assert.equal(dashboard.connectedApplications[0].clientId, 'independent-verifier'); await app.inject({ method: 'DELETE', url: '/connected-applications/independent-verifier', headers: uh }); assert.equal((await app.inject({ method: 'POST', url: '/proof-requests', headers: uh, payload: { clientId: 'independent-verifier', requestedClaims: ['adult_verified'] } })).statusCode, 400); await app.close(); });
test('logout and account deletion revoke access and credentials', async () => { const app = await buildApp(); const user = await app.privateId.register({ email: 'delete@example.test', password: 'secure delete password' }); const login = await app.privateId.login(user.email, 'secure delete password'), headers = { authorization: `Bearer ${login.accessToken}` }; assert.equal((await app.inject({ method: 'POST', url: '/auth/logout', headers })).statusCode, 200); assert.equal((await app.inject({ method: 'GET', url: '/sessions', headers })).statusCode, 401); const again = await app.privateId.login(user.email, 'secure delete password'), againHeaders = { authorization: `Bearer ${again.accessToken}` }; assert.equal((await app.inject({ method: 'DELETE', url: '/accounts/me', headers: againHeaders })).json().status, 'DEACTIVATED'); assert.equal((await app.inject({ method: 'POST', url: '/auth/token', payload: { email: user.email, password: 'secure delete password' } })).statusCode, 400); await app.close(); });
test('administration overview requires an independent admin role', async () => { const app = await buildApp(), user = await app.privateId.register({ email: 'role-user@example.test', password: 'role user password' }), admin = await app.privateId.register({ email: 'role-admin@example.test', password: 'role admin password', roles: ['SECURITY_ADMIN'] }); const u = await app.privateId.login(user.email, 'role user password'), a = await app.privateId.login(admin.email, 'role admin password'); assert.equal((await app.inject({ method: 'GET', url: '/admin/overview', headers: { authorization: `Bearer ${u.accessToken}` } })).statusCode, 403); assert.equal((await app.inject({ method: 'GET', url: '/admin/overview', headers: { authorization: `Bearer ${a.accessToken}` } })).json().customers, 2); await app.close(); });
test('session capabilities are authenticated and derived from assigned roles', async () => { const app = await buildApp(), issuer = await app.privateId.register({ email: 'cap-issuer@example.test', password: 'cap issuer password', roles: ['ISSUER_ADMIN'] }), login = await app.privateId.login(issuer.email, 'cap issuer password'); assert.equal((await app.inject({ method: 'GET', url: '/auth/capabilities' })).statusCode, 401); const result = await app.inject({ method: 'GET', url: '/auth/capabilities', headers: { authorization: `Bearer ${login.accessToken}` } }); assert.equal(result.statusCode, 200); assert.deepEqual(result.json().roles, ['ISSUER_ADMIN']); assert.ok(result.json().capabilities.includes('credentials.issue')); assert.ok(!result.json().capabilities.includes('audit.view')); await app.close(); });
test('federated sign-in proof requires a session and returns the configured client destination', async () => { const { app, auth } = await fixture(); assert.equal((await app.inject({ method: 'POST', url: '/federation/proof', payload: { clientId: 'relationship-network' } })).statusCode, 401); const result = await app.inject({ method: 'POST', url: '/federation/proof', headers: auth, payload: { clientId: 'relationship-network' } }); assert.equal(result.statusCode, 200); assert.ok(result.json().proof); assert.equal(result.json().redirectUrl, process.env.RELATIONSHIP_SITE_URL ?? 'http://localhost:3002/site/'); const verified = await app.inject({ method: 'POST', url: '/proofs/verify', payload: { proof: result.json().proof, audience: 'relationship-network' } }); assert.equal(verified.json().claims.account_valid, true); await app.close(); });
